<script setup lang="ts">
import {computed,nextTick,onUnmounted,ref,watch} from 'vue';
import {ArrowRight,ChevronDown,ChevronLeft,ChevronRight,GitCompareArrows,Paperclip,Pencil,Plus,Search,X} from 'lucide-vue-next';
import type {useJourney} from './useJourney';
import type {Exam} from './types';
import {EXAM_TYPES} from '../shared/exam-types.js';
import {COPY} from './copy';
const props=defineProps<{journey:ReturnType<typeof useJourney>}>();
const {data,current,total,maximum,exams,filtered,timeline,currentIndex,allSubjects,subject,rows,term,terms,typeFilter,query,fmt,date,urlFor,navigate,pickExam,photosFor,photoUrl,openPhoto,getExamType}=props.journey;
const timelineTrack=ref<HTMLElement|null>(null);
const view=ref<'exam'|'progress'>('exam'),range=ref('5'),directory=ref<HTMLDialogElement|null>(null),detail=ref<HTMLDialogElement|null>(null),attachments=ref<HTMLDialogElement|null>(null),activeDialog=ref<HTMLDialogElement|null>(null),limit=ref(20),focusId=ref('');
const colors=['#528bff','#5075ee','#5cbce8','#9278ec','#a595ef','#4bc39b','#5ac8ba','#e7ba4c','#ed948a'];
const score=(e:Exam|undefined,s:string)=>e?.scores.find(v=>v.subject===s);
const examSubjects=computed(()=>current.value?.scores.map(s=>s.subject)||[]);
const semesterOptions=computed(()=>{const options=terms.value.map(value=>{const grades=Array.from(new Set(exams.value.filter(e=>e.term===value).map(e=>e.grade?.trim()).filter(Boolean)));const half=value.match(/上学期|下学期/)?.[0]||value;return {value,label:grades.length?`${grades.join(' / ')} · ${half}`:value};});const counts=new Map<string,number>();for(const o of options)counts.set(o.label,(counts.get(o.label)||0)+1);return options.map(o=>({...o,label:counts.get(o.label)!>1?`${o.label}（${o.value}）`:o.label}));});
const semesterLabel=computed(()=>term.value==='全部学期'?'全部学期':semesterOptions.value.find(o=>o.value===term.value)?.label||term.value);

const previous=computed(()=>timeline.value[currentIndex.value-1]);
const next=computed(()=>timeline.value[currentIndex.value+1]);
const listed=computed(()=>filtered.value.slice(0,limit.value));
const recent=computed(()=>range.value==='all'?rows.value:rows.value.slice(-Number(range.value)));
const sameMax=computed(()=>new Set(recent.value.map(r=>r.score.max)).size<=1);
const ceiling=computed(()=>sameMax.value?(recent.value[0]?.score.max||100):100);
const chartPoints=computed(()=>recent.value.map((r,i)=>({...r,x:recent.value.length===1?350:55+i*590/(recent.value.length-1),y:220-(sameMax.value?r.score.score/ceiling.value:r.score.score/r.score.max)*175})));
const activePoint=computed(()=>chartPoints.value.find(p=>p.exam.id===focusId.value)||chartPoints.value.find(p=>p.exam.id===current.value?.id)||chartPoints.value.at(-1));
const chartLine=computed(()=>chartPoints.value.map(p=>`${p.x},${p.y}`).join(' '));
const detailExam=ref<Exam>();
const detailTotal=computed(()=>detailExam.value?.scores.reduce((sum,s)=>sum+s.score,0)||0);
const detailMaximum=computed(()=>detailExam.value?.scores.reduce((sum,s)=>sum+s.max,0)||0);
const historyLabels=computed(()=>chartPoints.value.filter((_,i,a)=>a.length<=5||i===0||i===a.length-1||i===Math.floor(a.length/2)));
const change=computed(()=>{const p=chartPoints.value;if(p.length<2)return '';const a=p.at(-1)!.score,b=p.at(-2)!.score;const d=sameMax.value?a.score-b.score:(a.score/a.max-b.score/b.max)*100;return `${d>0?'+':''}${fmt(d)} ${sameMax.value?'分':'个百分点'}`;});
watch([term,typeFilter,query],()=>limit.value=20);
watch(subject,()=>focusId.value='');
let centered=false,trackObserver:ResizeObserver|undefined;
async function centerTimeline(animate=false){await nextTick();const track=timelineTrack.value,node=track?.querySelector<HTMLElement>('[aria-current=true]');if(!track||!node)return;track.scrollTo({left:track.scrollLeft+node.getBoundingClientRect().left-track.getBoundingClientRect().left-track.clientWidth/2+node.clientWidth/2,behavior:animate&&!matchMedia('(prefers-reduced-motion: reduce)').matches?'smooth':'instant'});}
watch(()=>current.value?.id,()=>{void centerTimeline(centered);centered=true;},{flush:'post'});
watch(timelineTrack,el=>{trackObserver?.disconnect();if(el){trackObserver=new ResizeObserver(()=>void centerTimeline());trackObserver.observe(el);void centerTimeline();}},{flush:'post'});
function selectExam(e:Exam){pickExam(e.id);}
function progress(s?:string){if(s)subject.value=s;view.value='progress';}
let previousOverflow='',returnFocus:HTMLElement|null=null;
async function showDialog(el:HTMLDialogElement|null){if(!el)return;returnFocus=document.activeElement as HTMLElement;previousOverflow=document.body.style.overflow;activeDialog.value=el;document.body.style.overflow='hidden';el.showModal();}
function closeDialog(){const el=activeDialog.value;if(!el)return;activeDialog.value=null;el.close();document.body.style.overflow=previousOverflow;returnFocus?.focus({preventScroll:true});}
async function showDetails(e:Exam){detailExam.value=e;await nextTick();showDialog(detail.value);}
async function showAttachments(){detailExam.value=current.value;await nextTick();showDialog(attachments.value);}
async function edit(e:Exam){closeDialog();await navigate('/record/'+e.id+'/edit');}
function choose(e:Exam){closeDialog();selectExam(e);}
onUnmounted(()=>{trackObserver?.disconnect();if(activeDialog.value)document.body.style.overflow=previousOverflow;});
</script>

<template>
 <div class="growth-scroll">
  <header class="gs-intro"><div><h1 class="j-page-title" tabindex="-1">{{data.profile.nickname}}{{COPY.homeTitleSuffix}}</h1><p>{{COPY.homeSubtitle}}</p></div><a class="gs-record" :href="urlFor('/record/new')" @click.prevent="navigate('/record/new')"><Plus :size="18" aria-hidden="true"/>记一场考试</a></header>
  <section class="gs-journey" aria-label="考试时间线">
   <div class="gs-semester"><label class="gs-semester-picker"><select v-model="term" aria-label="选择学期"><option value="全部学期">全部学期</option><option v-for="o in semesterOptions" :key="o.value" :value="o.value">{{o.label}}</option></select><span class="gs-semester-value" aria-hidden="true"><span>{{semesterLabel}}</span><ChevronDown :size="16"/></span></label><button class="gs-directory-button" @click="showDialog(directory)"><Search :size="17" aria-hidden="true"/>考试目录<span>{{exams.length}}</span></button></div>
   <div v-if="timeline.length" class="gs-time-layout"><button class="gs-time-arrow" aria-label="上一场考试" :disabled="!previous" @click="previous&&selectExam(previous)"><ChevronLeft :size="20"/></button><div ref="timelineTrack" class="gs-time-track" role="group" aria-label="选择考试"><button v-for="e in timeline" :key="e.id" class="gs-time-node" :aria-current="current?.id===e.id?'true':undefined" :aria-label="e.title+' '+date(e.date)" @click="selectExam(e)"><span class="gs-node-dot"></span><strong>{{e.title}}</strong><small>{{date(e.date)}}</small></button></div><button class="gs-time-arrow" aria-label="下一场考试" :disabled="!next" @click="next&&selectExam(next)"><ChevronRight :size="20"/></button></div>
   <div v-else class="gs-empty"><h2>{{exams.length?'没有匹配的考试':'从第一场考试开始'}}</h2><p>{{exams.length?'在考试目录中调整搜索和筛选条件。':'先记下一次成绩，慢慢连成成长的轨迹。'}}</p><a v-if="!exams.length" class="j-button j-primary" :href="urlFor('/record/new')" @click.prevent="navigate('/record/new')">记录第一次考试<ArrowRight :size="16"/></a><button v-else class="j-text" @click="query='';term='全部学期';typeFilter='全部类型'">清除筛选</button></div>
  </section>
  <div class="gs-view-switch" role="group" aria-label="查看方式"><button :aria-pressed="view==='exam'" @click="view='exam'">{{COPY.examTab}}</button><button :aria-pressed="view==='progress'" @click="progress()">{{COPY.growthTab}}</button></div>
  <section v-if="current&&view==='exam'" class="gs-exam" aria-label="本场考试成绩">
   <aside class="gs-exam-context"><div class="gs-current-mark"><span></span>第 {{currentIndex+1}} / {{timeline.length}} 场记录</div><div class="gs-exam-title" :key="current.id"><h2>{{current.title}}</h2><p>{{date(current.date)}}<span>{{current.grade}}</span></p><small>{{current.term}}</small></div><div class="gs-total gs-exam-total" role="group" aria-label="本场总分"><span>总分</span><p><strong>{{fmt(total)}}</strong><small>/ {{fmt(maximum)}}</small></p><small>已录入 {{current.scores.length}} 科合计</small></div><div class="gs-ranks"><div class="gs-class-rank"><span>班级排名</span><strong>{{current.classRank??'—'}}</strong><small>{{current.classRank?'名':'未记录'}}</small></div><div class="gs-grade-rank"><span>年级排名</span><strong>{{current.gradeRank??'—'}}</strong><small>{{current.gradeRank?'名':'未记录'}}</small></div></div><div class="gs-context-actions"><button class="j-text" @click="showDetails(current)">本场详情<ChevronRight :size="15"/></button><a class="j-text" :href="urlFor('/record/'+current.id+'/edit')" @click.prevent="edit(current)"><Pencil :size="15" aria-hidden="true"/>编辑记录</a></div><p v-if="current.note" class="gs-note">{{current.note}}</p><button v-if="photosFor(current.id).length" class="gs-attachment" @click="showAttachments()"><Paperclip :size="17" aria-hidden="true"/>成绩截图 · {{photosFor(current.id).length}} 张<ChevronRight :size="14"/></button><a v-else class="gs-attachment gs-attachment-empty" :href="urlFor('/record/'+current.id+'/edit')" @click.prevent="edit(current)"><Paperclip :size="17" aria-hidden="true"/>添加成绩截图<span>选填</span></a></aside>
   <div class="gs-score-section"><header><h3>{{COPY.scoresHeading}}</h3><span>点击科目，查看历次变化</span></header><div class="gs-score-list" :key="current.id"><button v-for="(s,i) in examSubjects" :key="s" class="gs-score-row" :style="{'--subject-color':colors[i%colors.length]}" :aria-label="'查看'+s+COPY.growthTab" @click="progress(s)"><span class="gs-subject">{{s}}</span><span class="gs-score-track" aria-hidden="true"><i :style="{transform:'scaleX('+(score(current,s)?score(current,s)!.score/score(current,s)!.max:0)+')'}"></i></span><span v-if="score(current,s)" class="gs-value"><strong>{{fmt(score(current,s)!.score)}}</strong><small>/ {{fmt(score(current,s)!.max)}}</small></span><span v-else class="gs-value gs-missing">未录入</span><ChevronRight :size="14" class="gs-score-chevron" aria-hidden="true"/></button></div><footer class="gs-score-footer"><span>已记录 {{current.scores.length}} 科</span><a v-if="exams.length>1" class="j-text" :href="urlFor('/compare')" @click.prevent="navigate('/compare')"><GitCompareArrows :size="16" aria-hidden="true"/>选两场对照</a></footer></div>
  </section>
  <section v-else-if="view==='progress'" class="gs-progress" :aria-label="COPY.growthTab"><div class="gs-progress-controls"><div class="gs-subjects" role="group" aria-label="切换成绩科目"><button v-for="s in allSubjects" :key="s" :aria-pressed="subject===s" @click="subject=s">{{s}}</button></div><select v-model="range" aria-label="趋势考试范围"><option value="5">近5次考试</option><option value="10">近10次考试</option><option value="all">全部考试</option></select></div><div class="gs-progress-layout"><div class="gs-chart"><header><div><h2>{{subject}}成绩变化</h2><p>{{sameMax?'分数':'得分率 %'}} · {{recent.length}} 次记录</p></div><div v-if="change" class="gs-change"><span>最近两次变化</span><strong>{{change}}</strong></div></header><svg v-if="chartPoints.length" viewBox="0 0 700 270" role="img" :aria-label="subject+'历次考试'+(sameMax?'分数':'得分率')+'，详细数值见下方记录'"><defs><linearGradient id="gs-chart-fill" x1="0" y1="0" x2="0" y2="1"><stop stop-color="#3267f5" stop-opacity=".13"/><stop offset="1" stop-color="#3267f5" stop-opacity="0"/></linearGradient></defs><g v-for="n in [0,1,2,3,4]" :key="n"><line x1="55" x2="645" :y1="220-n*43.75" :y2="220-n*43.75"/><text x="40" :y="225-n*43.75" text-anchor="end">{{fmt(ceiling*n/4)}}</text></g><polygon v-if="chartPoints.length>1" :points="`55,220 ${chartLine} 645,220`" fill="url(#gs-chart-fill)"/><polyline v-if="chartPoints.length>1" :points="chartLine" class="gs-chart-line"/><g v-for="p in chartPoints" :key="p.exam.id"><circle :cx="p.x" :cy="p.y" :r="activePoint?.exam.id===p.exam.id?6:4"/><title>{{p.exam.title}}：{{fmt(p.score.score)}} / {{fmt(p.score.max)}}</title></g><text v-for="p in historyLabels" :key="p.exam.id" :x="p.x" y="250" text-anchor="middle">{{p.exam.date.slice(2).replaceAll('-','.')}}</text></svg><p class="gs-chart-note">{{!chartPoints.length?'还没有本科成绩，换个科目看看。':chartPoints.length===1?'只有一次记录，继续记录后即可观察变化。':!sameMax?'满分不同，已按得分率比较。原始分数保留在右侧记录中。':'不同考试难度可能不同，变化只作回顾。'}}</p></div><div class="gs-trend-records" aria-label="趋势成绩记录"><button v-for="p in chartPoints.slice().reverse()" :key="p.exam.id" :aria-pressed="activePoint?.exam.id===p.exam.id" @click="focusId=p.exam.id"><span><strong>{{p.exam.title}}</strong><small>{{date(p.exam.date)}}</small></span><b>{{fmt(p.score.score)}}<small>/ {{fmt(p.score.max)}}</small></b></button><button v-if="activePoint" class="gs-open-record" @click="selectExam(activePoint.exam);view='exam'">翻开这场考试<ArrowRight :size="16"/></button></div></div><a v-if="exams.length>1" class="j-text" :href="urlFor('/compare')" @click.prevent="navigate('/compare')"><GitCompareArrows :size="17"/>选择两场考试对照</a></section>
  <dialog ref="directory" class="j-dialog gs-directory" aria-labelledby="gs-directory-title" @cancel.prevent="closeDialog" @close="closeDialog"><header><div><h2 id="gs-directory-title">考试目录</h2><p>{{filtered.length}} 场记录，按时间倒序</p></div><button class="j-icon j-close" aria-label="关闭考试目录" autofocus @click="closeDialog"><X :size="22"/></button></header><div class="gs-directory-filters"><input v-model="query" aria-label="搜索考试" placeholder="搜索考试、科目或小记"><select v-model="typeFilter" aria-label="筛选考试类型"><option>全部类型</option><option v-for="t in [...EXAM_TYPES,'未分类']" :key="t">{{t}}</option></select></div><div class="gs-directory-list"><button v-for="e in listed" :key="e.id" :aria-current="e.id===current?.id?'true':undefined" @click="choose(e)"><span>{{date(e.date)}}</span><div><strong>{{e.title}}</strong><small>{{e.term}} · {{e.grade}}</small></div><ChevronRight :size="18"/></button><p v-if="!listed.length">没有匹配的考试，试试其他关键词。</p><button v-if="filtered.length>limit" class="gs-load-more" @click="limit+=20">再看 20 次考试</button></div></dialog>
  <dialog ref="detail" class="j-dialog gs-detail" aria-labelledby="gs-detail-title" @cancel.prevent="closeDialog" @close="closeDialog"><template v-if="detailExam"><header><div><p>{{date(detailExam.date)}} · {{detailExam.grade}}</p><h2 id="gs-detail-title">{{detailExam.title}}</h2></div><button class="j-icon j-close" aria-label="关闭考试详情" autofocus @click="closeDialog"><X :size="22"/></button></header><div class="gs-total gs-detail-total" role="group" aria-label="本场详情总分"><span>总分</span><p><strong>{{fmt(detailTotal)}}</strong><small>/ {{fmt(detailMaximum)}}</small></p><small>已录入 {{detailExam.scores.length}} 科合计</small></div><div class="gs-detail-scores"><div v-for="s in detailExam.scores" :key="s.subject"><span>{{s.subject}}</span><strong>{{fmt(s.score)}} <small>/ {{fmt(s.max)}}</small></strong></div></div><div class="gs-detail-ranks"><span>班级排名 <b>{{detailExam.classRank??'未记录'}}</b></span><span>年级排名 <b>{{detailExam.gradeRank??'未记录'}}</b></span></div><p v-if="detailExam.note" class="gs-note">{{detailExam.note}}</p><div v-if="photosFor(detailExam.id).length" class="gs-attachment-list"><button v-for="(p,i) in photosFor(detailExam.id)" :key="p.id" :aria-label="'放大成绩截图：'+p.label" @click="openPhoto(p)"><Paperclip :size="16"/>成绩截图 {{i+1}}<ChevronRight :size="14"/></button></div><footer><button class="j-outline" @click="edit(detailExam)"><Pencil :size="16"/>编辑这场考试</button><a v-if="exams.length>1" class="j-text" :href="urlFor('/compare')" @click.prevent="pickExam(detailExam.id);closeDialog();navigate('/compare')">和另一场对照</a></footer></template></dialog>
  <dialog ref="attachments" class="j-dialog gs-attachments" aria-labelledby="gs-attachments-title" @cancel.prevent="closeDialog" @close="closeDialog"><template v-if="detailExam"><header><div><h2 id="gs-attachments-title">成绩截图</h2><p>{{detailExam.title}} · {{date(detailExam.date)}}</p></div><button class="j-icon j-close" aria-label="关闭成绩截图" autofocus @click="closeDialog"><X :size="22"/></button></header><div class="gs-attachment-thumbs"><button v-for="p in photosFor(detailExam.id)" :key="p.id" :aria-label="'放大成绩截图：'+p.label" @click="openPhoto(p)"><img :src="photoUrl(p)" :alt="p.label" loading="lazy"/><span>点击放大</span></button></div></template></dialog>
 </div>
</template>
